(function () {
    var previousDevice = window.device;
    window.device = {};

    var documentElement = window.document.documentElement;
    var userAgent = window.navigator.userAgent.toLowerCase();

    // Проверка на платформы и устройства
    function contains(str) {
        return userAgent.indexOf(str) !== -1;
    }

    function hasClass(cls) {
        var regex = new RegExp(cls, "i");
        return documentElement.className.match(regex);
    }

    function addClass(cls) {
        if (!hasClass(cls)) {
            documentElement.className += " " + cls;
        }
    }

    function removeClass(cls) {
        if (hasClass(cls)) {
            documentElement.className = documentElement.className.replace(cls, "");
        }
    }

    // Устройства Apple
    device.ios = function () {
        return device.iphone() || device.ipod() || device.ipad();
    };

    device.iphone = function () {
        return contains("iphone");
    };

    device.ipod = function () {
        return contains("ipod");
    };

    device.ipad = function () {
        return contains("ipad");
    };

    // Android
    device.android = function () {
        return contains("android");
    };

    device.androidPhone = function () {
        return device.android() && contains("mobile");
    };

    device.androidTablet = function () {
        return device.android() && !contains("mobile");
    };

    // Blackberry
    device.blackberry = function () {
        return contains("blackberry") || contains("bb10") || contains("rim");
    };

    device.blackberryPhone = function () {
        return device.blackberry() && !contains("tablet");
    };

    device.blackberryTablet = function () {
        return device.blackberry() && contains("tablet");
    };

    // Windows
    device.windows = function () {
        return contains("windows");
    };

    device.windowsPhone = function () {
        return device.windows() && contains("phone");
    };

    device.windowsTablet = function () {
        return device.windows() && contains("touch") && !device.windowsPhone();
    };

    // Firefox OS
    device.fxos = function () {
        return (contains("(mobile;") || contains("(tablet;")) && contains("; rv:");
    };

    device.fxosPhone = function () {
        return device.fxos() && contains("mobile");
    };

    device.fxosTablet = function () {
        return device.fxos() && contains("tablet");
    };

    // Meego
    device.meego = function () {
        return contains("meego");
    };

    // Cordova
    device.cordova = function () {
        return window.cordova && location.protocol === "file:";
    };

    // Node Webkit
    device.nodeWebkit = function () {
        return typeof window.process === "object";
    };

    // Устройства
    device.mobile = function () {
        return (
            device.androidPhone() ||
            device.iphone() ||
            device.ipod() ||
            device.windowsPhone() ||
            device.blackberryPhone() ||
            device.fxosPhone() ||
            device.meego()
        );
    };

    device.tablet = function () {
        return (
            device.ipad() ||
            device.androidTablet() ||
            device.blackberryTablet() ||
            device.windowsTablet() ||
            device.fxosTablet()
        );
    };

    device.desktop = function () {
        return !device.tablet() && !device.mobile();
    };

    // Ориентация
    device.portrait = function () {
        return window.innerHeight / window.innerWidth > 1;
    };

    device.landscape = function () {
        return window.innerHeight / window.innerWidth < 1;
    };

    // Конфликт с другими скриптами
    device.noConflict = function () {
        window.device = previousDevice;
        return this;
    };

    // Добавление классов к <html> по типу устройства
    if (device.ios()) {
        if (device.ipad()) {
            addClass("ios ipad tablet");
        } else if (device.iphone()) {
            addClass("ios iphone mobile");
        } else if (device.ipod()) {
            addClass("ios ipod mobile");
        }
    } else if (device.android()) {
        addClass(device.androidTablet() ? "android tablet" : "android mobile");
    } else if (device.blackberry()) {
        addClass(device.blackberryTablet() ? "blackberry tablet" : "blackberry mobile");
    } else if (device.windows()) {
        if (device.windowsTablet()) {
            addClass("windows tablet");
        } else if (device.windowsPhone()) {
            addClass("windows mobile");
        } else {
            addClass("desktop");
        }
    } else if (device.fxos()) {
        addClass(device.fxosTablet() ? "fxos tablet" : "fxos mobile");
    } else if (device.meego()) {
        addClass("meego mobile");
    } else if (device.nodeWebkit()) {
        addClass("node-webkit");
    } else {
        addClass("desktop");
    }

    if (device.cordova()) {
        addClass("cordova");
    }

    // Обновление ориентации (landscape / portrait)
    function updateOrientation() {
        if (device.landscape()) {
            removeClass("portrait");
            addClass("landscape");
        } else {
            removeClass("landscape");
            addClass("portrait");
        }
    }

    var orientationEvent = "onorientationchange" in window ? "orientationchange" : "resize";

    if (window.addEventListener) {
        window.addEventListener(orientationEvent, updateOrientation, false);
    } else if (window.attachEvent) {
        window.attachEvent(orientationEvent, updateOrientation);
    } else {
        window[orientationEvent] = updateOrientation;
    }

    // Инициализировать ориентацию
    updateOrientation();
}).call(this);
